from Pynite import FEModel3D

def case_a():
    m = FEModel3D()
    m.add_material('steel', 29000, 11200, 0.3, 0.284)
    m.add_section('S', 10, 100, 150, 250)
    for n,x,y,z in (('p',0,0,0),('q',6,1,2),('r',2,7,0.5)):
        m.add_node(n,x,y,z)
    for n,i,j in (('e1','p','q'),('e2','q','r'),('e3','r','p')):
        m.add_member(n,i,j,'steel','S')
    m.def_support('p',1,1,1,0,0,0)
    m.def_support('q',0,1,1,0,0,0)
    m.add_node_load('r','FY',2)
    return m

def control():
    m = FEModel3D()
    m.add_node('n1',0,0,0); m.add_node('n2',10,0,0)
    m.add_material('steel',29000,11200,0.3,0.284)
    m.add_section('S',10,100,150,250)
    m.add_member('m','n1','n2','steel','S')
    m.def_support('n1',1,1,1,1,1,1)
    m.def_support('n2',0,1,1,0,0,0)
    m.add_member_dist_load('m','Fy',-1,-1)
    return m

def portal():
    # Stable 2-bay portal: well-conditioned, must NOT false-positive.
    m = FEModel3D()
    m.add_material('steel',29000,11200,0.3,0.284)
    m.add_section('S',10,100,150,250)
    for n,x in (('a',0),('b',10),('c',20)):
        m.add_node(n,x,0,0)
        m.add_node(n+'t',x,10,0)
    for n in ('a','b','c'):
        m.add_member('col'+n,n,n+'t','steel','S')
    m.add_member('b1','at','bt','steel','S')
    m.add_member('b2','bt','ct','steel','S')
    for n in ('a','b','c'):
        m.def_support(n,1,1,1,1,1,1)
    m.add_node_load('bt','FX',5)
    return m

def run(factory, method, sparse, **kw):
    m = factory()
    try:
        getattr(m, method)(sparse=sparse, **kw)
        return ('ok', None)
    except Exception as e:
        return ('exc', type(e).__name__)

print(\"== analyze (default) ==\")
for fac, name in ((case_a,'case_a'),(control,'control'),(portal,'portal')):
    for sp in (True, False):
        r = run(fac,'analyze',sp, check_statics=False)
        print(f\"  {name:8s} sparse={sp"'!s:5s} -> {r}")

print("== analyze(check_stability=False)  [previously broken] ==")
for fac, name in ((case_a,'"'case_a'),(control,'control'),(portal,'portal')):
